const python = path.join(root, "venvs/more-itertools/bin/python");
const support = path.join(root, "validation/more-itertools-1247/checkout");
const versions = [
  { version: "parent", source: gitSource("2fe1b2eeb9d75f994113fe3ac76d14b6bcd6fb10") },
  { version: "upstream_reference", source: gitSource("dc2664b4a7c66209485c9f5e359137bf4b365eb3") },
  ...trials.map((r) => {
    const trial = path.dirname(r.result_file).replace(/\/results\/.+$/, "");
    return { version: `${r.cell}-r${r.repetition}`, cell: r.cell, run: r.repetition,
      source: fs.readFileSync(path.join(trial, "runs", r.task, `${r.cell}-r${r.repetition}`, "more_itertools/more.py"), "utf8") };
  }),
];
const results = versions.map(({ source, ...meta }) => {
  const checks = [
    ...["finite_float_huge_range", "decimal_precision_2"].flatMap((name) => ["contains", "index"].map((operation) => [name, operation])),
    ...["datetime_upper_bound", "datetime_lower_bound"].flatMap((name) => ["len", "first"].map((operation) => [name, operation]))
  ];
  const cases = checks.map(([name, operation]) => {
    const test = cp.spawnSync(python, ["-B", "-c", program], { input: JSON.stringify({ source, support, case_filter: [name, operation] }), encoding: "utf8", timeout: 10000,
      env: { ...process.env, PYTHONDONTWRITEBYTECODE: "1" } });
    if (test.error || test.status !== 0) return { case: name, operation, passed: false, exit: test.status,
      timed_out: test.error?.code === "ETIMEDOUT", execution_error: String(test.error?.code || test.stderr || "Nonzero probe exit").slice(-800) };
    const rows = JSON.parse(test.stdout);
    if (rows.length !== 1) throw new Error("Expected exactly one quality probe outcome");
    return rows[0];
  });
  return { ...meta, source_sha256: crypto.createHash("sha256").update(source).digest("hex"), cases };
});
